import{_ as e,o as d,c as r,a8 as o}from"./chunks/framework.BppdKxCY.js";const b=JSON.parse('{"title":"🗺️ 前端常用库学习路线：RxJS · Lodash · XLSX · Day.js · Zod","description":"","frontmatter":{},"headers":[],"relativePath":"libraries-learning-path.md","filePath":"libraries-learning-path.md","lastUpdated":1793421673000}'),a={name:"libraries-learning-path.md"};function l(s,t,n,h,c,i){return d(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="🗺️-前端常用库学习路线-rxjs-·-lodash-·-xlsx-·-day-js-·-zod" tabindex="-1">🗺️ 前端常用库学习路线：RxJS · Lodash · XLSX · Day.js · Zod <a class="header-anchor" href="#🗺️-前端常用库学习路线-rxjs-·-lodash-·-xlsx-·-day-js-·-zod" aria-label="Permalink to &quot;🗺️ 前端常用库学习路线：RxJS · Lodash · XLSX · Day.js · Zod&quot;">​</a></h1><blockquote><p>这份路线解决三个问题：<strong>先学哪个</strong>、<strong>每个库学到什么程度算过关</strong>、<strong>如何避免「会用 API 但一上业务就踩坑」</strong>。五个库分别对应五类真实需求——日期、数据变换、运行时校验、异步流、表格文件——它们不是孤立的 API 集合，而是五种工程思维方式。</p><p>配套实验工程：<a href="./libraries/README">libraries/</a>（pnpm workspace，五个包各自带 <code>src/</code> 与回归测试）；配套教程：<a href="./29-rxjs">RxJS</a>、<a href="./30-lodash">Lodash</a>、<a href="./31-xlsx">XLSX</a>、<a href="./32-dayjs">Day.js</a>、<a href="./33-zod">Zod</a>。</p></blockquote><hr><h2 id="一、先建立选型坐标" tabindex="-1">一、先建立选型坐标 <a class="header-anchor" href="#一、先建立选型坐标" aria-label="Permalink to &quot;一、先建立选型坐标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>库</th><th>一句话定位</th><th>核心心智模型</th><th>上手难度</th><th>业务出场率</th><th>主要替代</th></tr></thead><tbody><tr><td><a href="./32-dayjs">Day.js</a></td><td>2KB 级日期库</td><td>不可变的时间包装器 + 插件</td><td>★☆☆☆☆</td><td>极高</td><td>Native <code>Intl</code> / Temporal / date-fns</td></tr><tr><td><a href="./30-lodash">Lodash</a></td><td>数据与函数工具集</td><td>集合变换 + 惰性管线 + FP</td><td>★★☆☆☆</td><td>极高</td><td>原生 ES2023 / es-toolkit</td></tr><tr><td><a href="./33-zod">Zod</a></td><td>运行时 Schema 校验</td><td>Schema 是唯一事实来源，类型由它推导</td><td>★★★☆☆</td><td>高</td><td>Valibot / ArkType / io-ts</td></tr><tr><td><a href="./29-rxjs">RxJS</a></td><td>异步事件流编程</td><td>Observable：可取消、可组合的推送流</td><td>★★★★☆</td><td>中高</td><td>原生事件 + AbortController / 响应式信号</td></tr><tr><td><a href="./31-xlsx">XLSX</a></td><td>电子表格读写</td><td>Workbook → Worksheet → Cell 三层模型</td><td>★★★☆☆</td><td>中（中后台/数据产品高）</td><td>ExcelJS / 服务端导出</td></tr></tbody></table><h3 id="三条选型原则" tabindex="-1">三条选型原则 <a class="header-anchor" href="#三条选型原则" aria-label="Permalink to &quot;三条选型原则&quot;">​</a></h3><ol><li><strong>平台已内置的，先问「真的需要库吗」</strong>：<a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>Intl.DateTimeFormat</code></a>、<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/structuredClone" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>structuredClone</code></a>、<code>Array.prototype.group</code>、<code>Object.groupBy</code> 已能覆盖不少场景；引入库的理由应该是「跨浏览器一致性、可测试性、边界处理成本」，而不是「写得短」。</li><li><strong>体积看「进入首屏的字节」，不是 <code>node_modules</code> 大小</strong>：优先 ESM + 按需导入 + tree-shaking；Lodash 用 <code>lodash-es</code> 而不是整体 <code>lodash</code>，Day.js 的 locale 与插件按需注册。</li><li><strong>安全与数据边界优先于开发体验</strong>：Zod 守 API/表单/环境变量边界；XLSX 与 CSV 导入必须限制大小、校验字段、防公式注入；Lodash <code>merge</code> 必须防原型污染。</li></ol><hr><h2 id="二、三阶段能力模型-每个库都按这个标尺验收" tabindex="-1">二、三阶段能力模型（每个库都按这个标尺验收） <a class="header-anchor" href="#二、三阶段能力模型-每个库都按这个标尺验收" aria-label="Permalink to &quot;二、三阶段能力模型（每个库都按这个标尺验收）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>验收标准</th><th>常见误区</th></tr></thead><tbody><tr><td>L1 会用</td><td>能照着文档完成常见任务</td><td>不查文档写出格式化、分组、校验、请求重试、表格导出；知道 API 的返回类型与副作用</td><td>只会复制粘贴；把库当黑盒；忽略错误分支</td></tr><tr><td>L2 会选</td><td>能为场景选对 API，并控制体积与边界</td><td>能解释为什么用 <a href="https://rxjs.dev/api/index?tab=rxjs#switchMap" target="_blank" rel="noopener noreferrer" title="官方文档"><code>switchMap</code></a> 而不是 <a href="https://rxjs.dev/api/index?tab=rxjs#mergeMap" target="_blank" rel="noopener noreferrer" title="官方文档"><code>mergeMap</code></a>；能说清 <a href="https://lodash.com/docs/4.17.21#cloneDeep" target="_blank" rel="noopener noreferrer" title="官方文档"><code>cloneDeep</code></a> 与 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/structuredClone" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>structuredClone</code></a> 的差异；能做按需引入与代码分割</td><td>全量引入；在渲染函数里重建 Schema；用 <code>_.get</code> 掩盖数据结构问题</td></tr><tr><td>L3 会改</td><td>能读源码、封装团队级工具、定位性能问题</td><td>能写出可复用的请求流/校验层/表格管线；能定位订阅泄漏、时区错乱、内存暴涨；能写回归测试锁住行为</td><td>只会调用不会封装；出问题只能换库；没有测试</td></tr></tbody></table><blockquote><p><strong>精通不是背完 API</strong>。真正的分水岭是：你能把库的能力封装成团队可复用、可测试、可观测的边界层，并且在它与框架、TypeScript、构建工具冲突时做出取舍。</p></blockquote><hr><h2 id="三、推荐学习顺序" tabindex="-1">三、推荐学习顺序 <a class="header-anchor" href="#三、推荐学习顺序" aria-label="Permalink to &quot;三、推荐学习顺序&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Day.js  →  Lodash  →  Zod  →  RxJS  →  XLSX</span></span>
<span class="line"><span>（日期）   （数据变换） （数据边界）（异步流） （文件）</span></span>
<span class="line"><span>   │          │          │         │        │</span></span>
<span class="line"><span>   └──────────┴──────────┴─────────┴────────┘</span></span>
<span class="line"><span>        每一站都回到 libraries/ 跑通对应测试</span></span></code></pre></div><p><strong>为什么是这个顺序</strong>：</p><ol><li><strong>Day.js 最短平快</strong>：一天内能建立「不可变 + 插件」的直觉，先获得正反馈。</li><li><strong>Lodash 承接数据变换</strong>：分组、排序、去重、深拷贝是后面所有业务的地基；同时借它理解 tree-shaking 与函数式组合。</li><li><strong>Zod 建立边界意识</strong>：先学会「外部数据不可信」，再去处理异步流，会自然理解为什么请求层要做解码与校验。</li><li><strong>RxJS 难度最高但收益最大</strong>：它把取消、竞态、重试、多播统一成流模型；放在 Zod 之后，是因为「流里传什么」必须先有类型与 Schema。</li><li><strong>XLSX 是领域应用题</strong>：它同时用到日期、数据变换、校验与异步（Worker/上传下载），适合作为结业项目。</li></ol><hr><h2 id="四、逐库学习路线与验收清单" tabindex="-1">四、逐库学习路线与验收清单 <a class="header-anchor" href="#四、逐库学习路线与验收清单" aria-label="Permalink to &quot;四、逐库学习路线与验收清单&quot;">​</a></h2><h3 id="第-1-站-day-js-——-日期不是字符串" tabindex="-1">第 1 站：Day.js —— 日期不是字符串 <a class="header-anchor" href="#第-1-站-day-js-——-日期不是字符串" aria-label="Permalink to &quot;第 1 站：Day.js —— 日期不是字符串&quot;">​</a></h3><p><strong>章节入口</strong>：<a href="./32-dayjs">第三十二部分：Day.js 日期工程</a>｜<strong>实验包</strong>：<code>libraries/packages/dayjs-lab/</code></p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>动手作业</th><th>过关标准</th></tr></thead><tbody><tr><td>L1</td><td>parse / format / add / subtract / startOf / diff / isBefore</td><td>写一个「今天 / 昨天 / 本周 / 本月」筛选项</td><td>能说清 <a href="https://day.js.org/docs/api/display#format-string-string-" target="_blank" rel="noopener noreferrer" title="官方文档"><code>format</code></a> 只是展示层，存储永远用 ISO 或时间戳</td></tr><tr><td>L2</td><td>插件：utc / timezone / customParseFormat / relativeTime / duration / isBetween</td><td>实现「跨时区活动开始时间 + 倒计时 + 相对时间」</td><td>知道插件必须注册；知道 <code>tz</code> 转换后偏移何时刷新</td></tr><tr><td>L3</td><td>DST、locale、周起始、Temporal 对比、测试固定时钟</td><td>封装 <code>businessDaysBetween</code> / <code>monthBounds</code> 并写测试</td><td>能解释月末、闰年、DST 三类边界；测试不依赖当前时间</td></tr></tbody></table><p><strong>关键取舍</strong>：只在展示层做时区转换，服务端与存储统一 UTC；业务日期（生日、账期）用「日期字符串」而不是时间戳，避免时区把日期挪一天。</p><h3 id="第-2-站-lodash-——-数据变换的瑞士军刀" tabindex="-1">第 2 站：Lodash —— 数据变换的瑞士军刀 <a class="header-anchor" href="#第-2-站-lodash-——-数据变换的瑞士军刀" aria-label="Permalink to &quot;第 2 站：Lodash —— 数据变换的瑞士军刀&quot;">​</a></h3><p><strong>章节入口</strong>：<a href="./30-lodash">第三十部分：Lodash 工具库实战</a>｜<strong>实验包</strong>：<code>libraries/packages/lodash-lab/</code></p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>动手作业</th><th>过关标准</th></tr></thead><tbody><tr><td>L1</td><td><code>map/filter/reduce</code>、<a href="https://lodash.com/docs/4.17.21#groupBy" target="_blank" rel="noopener noreferrer" title="官方文档"><code>groupBy</code></a>、<a href="https://lodash.com/docs/4.17.21#orderBy" target="_blank" rel="noopener noreferrer" title="官方文档"><code>orderBy</code></a>、<a href="https://lodash.com/docs/4.17.21#uniqBy" target="_blank" rel="noopener noreferrer" title="官方文档"><code>uniqBy</code></a>、<code>get</code>、<code>pick</code>、<code>omit</code></td><td>把接口返回的扁平列表聚合成看板</td><td>能区分「返回新对象」与「原地修改」；不滥用 <code>_.get</code></td></tr><tr><td>L2</td><td>iteratee 简写、<code>debounce/throttle</code> 的 leading/trailing/cancel/flush、<a href="https://lodash.com/docs/4.17.21#memoize" target="_blank" rel="noopener noreferrer" title="官方文档"><code>memoize</code></a>、<a href="https://lodash.com/docs/4.17.21#cloneDeep" target="_blank" rel="noopener noreferrer" title="官方文档"><code>cloneDeep</code></a></td><td>做搜索防抖 + 表单草稿保存 + 深拷贝快照</td><td>能解释 <a href="https://lodash.com/docs/4.17.21#debounce" target="_blank" rel="noopener noreferrer" title="官方文档"><code>debounce</code></a> 的 <code>cancel/flush</code> 时机；知道 <a href="https://lodash.com/docs/4.17.21#cloneDeep" target="_blank" rel="noopener noreferrer" title="官方文档"><code>cloneDeep</code></a> 不能克隆函数/DOM</td></tr><tr><td>L3</td><td>FP 模块 <code>flow/curry</code>、惰性求值、原型污染、体积治理、es-toolkit 替代</td><td>用 <a href="https://lodash.com/docs/4.17.21#flow" target="_blank" rel="noopener noreferrer" title="官方文档"><code>flow</code></a> 重写一条数据清洗管线，并替换 3 个自写工具</td><td>能逐条说明为什么保留/移除某个 Lodash 依赖</td></tr></tbody></table><p><strong>关键取舍</strong>：新项目优先 <code>lodash-es</code> + 具名导入；只有复杂对象变换才引入 Lodash，简单数组操作交给原生；<code>merge</code> 处理不可信输入时必须过滤 <a href="[object Object]" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>__proto__</code></a>。</p><h3 id="第-3-站-zod-——-让类型在运行时也成立" tabindex="-1">第 3 站：Zod —— 让类型在运行时也成立 <a class="header-anchor" href="#第-3-站-zod-——-让类型在运行时也成立" aria-label="Permalink to &quot;第 3 站：Zod —— 让类型在运行时也成立&quot;">​</a></h3><p><strong>章节入口</strong>：<a href="./33-zod">第三十三部分：Zod 运行时校验</a>｜<strong>实验包</strong>：<code>libraries/packages/zod-lab/</code></p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>动手作业</th><th>过关标准</th></tr></thead><tbody><tr><td>L1</td><td>primitive / object / array / enum、<a href="https://zod.dev/?id=basic-usage" target="_blank" rel="noopener noreferrer" title="官方文档"><code>parse</code></a> 与 <a href="https://zod.dev/?id=basic-usage" target="_blank" rel="noopener noreferrer" title="官方文档"><code>safeParse</code></a>、<a href="https://zod.dev/?id=inferring-the-type-of-a-schema-with-zod-and-typescript" target="_blank" rel="noopener noreferrer" title="官方文档"><code>z.infer</code></a></td><td>为用户资料表单写 Schema 并渲染错误</td><td>知道 TS 类型在运行时不存在，接口数据必须校验</td></tr><tr><td>L2</td><td><code>optional/nullable/default/catch</code>、<code>transform</code>、<code>refine</code>、<code>coerce</code>、<code>discriminatedUnion</code></td><td>校验分页参数、API 信封、登录/注册联合类型</td><td>能区分「类型错误」与「业务规则错误」，并给出字段级错误</td></tr><tr><td>L3</td><td>泛型 Schema 工厂、递归 Schema、错误树、性能、RHF/OpenAPI/env 集成</td><td>做一层「API 响应解码器 + 表单 Schema 复用」</td><td>Schema 只创建一次；错误可定位到字段；前后端共享同一份契约</td></tr></tbody></table><p><strong>关键取舍</strong>：Schema 放在「边界」而不是「每次渲染」；<a href="https://zod.dev/?id=inferring-the-type-of-a-schema-with-zod-and-typescript" target="_blank" rel="noopener noreferrer" title="官方文档"><code>z.infer</code></a> 是类型的唯一来源；对不可信输入先 <a href="https://zod.dev/?id=basic-usage" target="_blank" rel="noopener noreferrer" title="官方文档"><code>safeParse</code></a>，不要把异常当控制流。</p><h3 id="第-4-站-rxjs-——-把异步事件当集合处理" tabindex="-1">第 4 站：RxJS —— 把异步事件当集合处理 <a class="header-anchor" href="#第-4-站-rxjs-——-把异步事件当集合处理" aria-label="Permalink to &quot;第 4 站：RxJS —— 把异步事件当集合处理&quot;">​</a></h3><p><strong>章节入口</strong>：<a href="./29-rxjs">第二十九部分：RxJS 响应式编程</a>｜<strong>实验包</strong>：<code>libraries/packages/rxjs-lab/</code></p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>动手作业</th><th>过关标准</th></tr></thead><tbody><tr><td>L1</td><td>Observable / Subscription / Subject、创建操作符、<a href="https://rxjs.dev/api/index?tab=rxjs#pipe" target="_blank" rel="noopener noreferrer" title="官方文档"><code>pipe</code></a>、取消订阅</td><td>把输入框事件变成可取消的搜索流</td><td>能说清 cold/hot、subscribe 返回什么、为什么必须取消</td></tr><tr><td>L2</td><td><code>switchMap/concatMap/mergeMap/exhaustMap</code>、<code>catchError/retry/finalize</code>、<a href="https://rxjs.dev/api/index?tab=rxjs#shareReplay" target="_blank" rel="noopener noreferrer" title="官方文档"><code>shareReplay</code></a></td><td>实现搜索防竞态 + 失败重试 + 结果缓存</td><td>能按「是否需要并发/是否保留顺序/是否丢弃旧请求」选对拍平操作符</td></tr><tr><td>L3</td><td>调度器、背压、多播、TestScheduler、源码结构、框架集成</td><td>封装请求管线并写 marble/假时钟测试</td><td>能定位订阅泄漏；能解释 <a href="https://rxjs.dev/api/index?tab=rxjs#shareReplay" target="_blank" rel="noopener noreferrer" title="官方文档"><code>shareReplay</code></a> 的引用计数与重放风险</td></tr></tbody></table><p><strong>关键取舍</strong>：一个事件流只订阅一次，用 <a href="https://rxjs.dev/api/index?tab=rxjs#shareReplay" target="_blank" rel="noopener noreferrer" title="官方文档"><code>shareReplay</code></a> 多播；视图层销毁必须 <a href="https://rxjs.dev/api/index?tab=rxjs#takeUntil" target="_blank" rel="noopener noreferrer" title="官方文档"><code>takeUntil</code></a>；能用 <code>AbortController + async/await</code> 解决的简单竞态，不必上 RxJS。</p><h3 id="第-5-站-xlsx-——-表格是数据管线-不是文件按钮" tabindex="-1">第 5 站：XLSX —— 表格是数据管线，不是文件按钮 <a class="header-anchor" href="#第-5-站-xlsx-——-表格是数据管线-不是文件按钮" aria-label="Permalink to &quot;第 5 站：XLSX —— 表格是数据管线，不是文件按钮&quot;">​</a></h3><p><strong>章节入口</strong>：<a href="./31-xlsx">第三十一部分：XLSX 表格工程</a>｜<strong>实验包</strong>：<code>libraries/packages/xlsx-lab/</code></p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>动手作业</th><th>过关标准</th></tr></thead><tbody><tr><td>L1</td><td>Workbook/Worksheet/Cell、JSON↔Sheet、<code>sheet_to_json</code>、<code>json_to_sheet</code>、CSV</td><td>导出带中文与日期的订单表</td><td>能说清 cell 的 <code>t/v/w</code> 三个字段；知道日期是序列值</td></tr><tr><td>L2</td><td>多 Sheet、公式、合并单元格、<code>cellDates</code>、列宽、Blob 下载、导入校验</td><td>做「模板下载 + 导入预览 + 错误行提示」</td><td>能处理空行、中文、日期、公式注入；知道社区版样式限制</td></tr><tr><td>L3</td><td>大文件内存、流式/分块、Worker、ZIP 炸弹与体积限制、ExcelJS 选型</td><td>把 10 万行导出移入 Worker 并压测</td><td>能估算内存峰值；主线程不卡顿；失败可回退服务端导出</td></tr></tbody></table><p><strong>关键取舍</strong>：导出大于约 5 万行优先服务端生成；浏览器端必须 Worker + 进度；导入永远「先解析预览、再校验、最后入库」，不要直接信任文件内容。</p><hr><h2 id="五、动画、工具链与构建库-第-54-55-册" tabindex="-1">五、动画、工具链与构建库（第 54 / 55 册） <a class="header-anchor" href="#五、动画、工具链与构建库-第-54-55-册" aria-label="Permalink to &quot;五、动画、工具链与构建库（第 54 / 55 册）&quot;">​</a></h2><p>前五个库解决「数据与异步」，这一组解决「动效、协议工具与构建产物」——它们的共同点是<strong>用得对很省事，用错了会悄悄拖垮包体或交互</strong>。逐库深入见 <a href="./54-animation-tooling">第五十四部分：动画与工具库</a> 与 <a href="./55-build-style-tooling">第五十五部分：构建与样式库</a>。</p><table tabindex="0"><thead><tr><th>库</th><th>一句话定位</th><th>核心心智模型</th><th>上手难度</th><th>业务出场率</th><th>主要替代</th><th>章节</th></tr></thead><tbody><tr><td><a href="https://motion.dev/" target="_blank" rel="noreferrer">framer-motion</a></td><td>React 声明式动画</td><td>把动画写成状态，<code>layout</code> 自动补间</td><td>★★☆☆☆</td><td>中高（React 项目）</td><td>CSS transition / react-spring</td><td><a href="./54-animation-tooling">54</a></td></tr><tr><td><a href="https://gsap.com/" target="_blank" rel="noreferrer">GSAP</a></td><td>命令式时间线引擎</td><td>Timeline 是可 seek、可嵌套的时间轴</td><td>★★★☆☆</td><td>中（复杂动效/大屏）</td><td>Web Animations API / anime.js</td><td><a href="./54-animation-tooling">54</a></td></tr><tr><td><a href="https://github.com/auth0/jwt-decode" target="_blank" rel="noreferrer">jwt-decode</a></td><td>JWT 负载解码</td><td>只解码不校验，服务端才是裁判</td><td>★☆☆☆☆</td><td>高</td><td>手写 base64url 解码</td><td><a href="./54-animation-tooling">54</a></td></tr><tr><td><a href="https://github.com/ljharb/qs" target="_blank" rel="noreferrer">qs</a></td><td>查询串序列化</td><td>嵌套/数组的括号语法有约定，前后端要对齐</td><td>★★☆☆☆</td><td>中高</td><td><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/URLSearchParams" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>URLSearchParams</code></a></td><td><a href="./54-animation-tooling">54</a></td></tr><tr><td><a href="https://github.com/uuidjs/uuid" target="_blank" rel="noreferrer">uuid</a></td><td>唯一 ID 生成</td><td>v4 随机不可排序，v7 时间前缀可排序</td><td>★☆☆☆☆</td><td>高</td><td><a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Crypto/randomUUID" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>crypto.randomUUID()</code></a></td><td><a href="./54-animation-tooling">54</a></td></tr><tr><td><a href="https://postcss.org/" target="_blank" rel="noreferrer">PostCSS</a></td><td>CSS 编译管线</td><td>插件按顺序改 AST，顺序即语义</td><td>★★★☆☆</td><td>高（构建链）</td><td>Lightning CSS / Sass</td><td><a href="./55-build-style-tooling">55</a></td></tr><tr><td><a href="https://vite.dev/" target="_blank" rel="noreferrer">Vite</a></td><td>开发/构建工具</td><td>开发期原生 ESM + 预构建，构建期 Rollup</td><td>★★★☆☆</td><td>极高</td><td>Webpack / Rspack</td><td><a href="./55-build-style-tooling">55</a></td></tr><tr><td><a href="https://webpack.js.org/" target="_blank" rel="noreferrer">Webpack</a></td><td>模块打包器</td><td>入口图 + loader/plugin 钩子 + 分包策略</td><td>★★★★☆</td><td>高（存量项目）</td><td>Vite / Rspack / esbuild</td><td><a href="./55-build-style-tooling">55</a></td></tr></tbody></table><p><strong>这一组的推荐顺序</strong>：<code>uuid / jwt-decode / qs</code>（半天，纯工具，先建立「协议边界」意识）→ <code>PostCSS</code>（半天，理解构建管线）→ <code>framer-motion</code> 或 <code>GSAP</code>（按项目栈二选一）→ <code>Vite</code>（一周，吃透预构建与 base）→ <code>Webpack</code>（按需，存量项目维护时再深入）。</p><p><strong>四条一句话避坑</strong>：</p><ol><li><code>jwt-decode</code> 解出来的 <code>exp</code> 只是提示——<strong>前端判断过期只是为了体验，鉴权必须由服务端做</strong>；</li><li><code>qs</code> 的 <code>arrayFormat</code> 必须与后端解析器一致，否则 <code>ids[]=1</code> 与 <code>ids=1</code> 会被解析成不同结构；</li><li>framer-motion 的 <code>layout</code> 动画只对<strong>同一父级内的兄弟节点</strong>可靠，跨路由/跨 Portal 的位移动画要手动 <code>layoutId</code> 并处理挂载时序；</li><li>Vite 的 <code>base</code> 决定产物里所有静态资源路径，子路径部署时<strong>必须与 Nginx 的 location 前缀一致</strong>，否则白屏只在生产出现。</li></ol><hr><h2 id="六、四周冲刺版-已有-1-3-年经验" tabindex="-1">六、四周冲刺版（已有 1~3 年经验） <a class="header-anchor" href="#六、四周冲刺版-已有-1-3-年经验" aria-label="Permalink to &quot;六、四周冲刺版（已有 1~3 年经验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主线</th><th>产出</th></tr></thead><tbody><tr><td>第 1 周</td><td>Day.js + Lodash 的 L1/L2</td><td>一个「日期筛选 + 数据看板聚合」页面，附带单元测试</td></tr><tr><td>第 2 周</td><td>Zod 的 L1/L2 + 与表单集成</td><td>登录/注册/分页查询三套 Schema，错误提示可定位到字段</td></tr><tr><td>第 3 周</td><td>RxJS 的 L1/L2</td><td>搜索联想：防抖 + 取消旧请求 + 失败重试 + 空态/错误态</td></tr><tr><td>第 4 周</td><td>XLSX 的 L1/L2 + 结业整合</td><td>订单导出 + 模板导入校验，日期与金额格式化正确</td></tr></tbody></table><blockquote><p>每周结束回到 <a href="./libraries/README">libraries/</a> 跑 <code>pnpm test</code>，确保示例行为与文档一致；结业项目建议把这五个库串成一条真实业务链：<strong>表单（Zod）→ 请求流（RxJS）→ 数据变换（Lodash）→ 日期展示（Day.js）→ 导出（XLSX）</strong>。</p></blockquote><hr><h2 id="七、通用学习方法-四步闭环" tabindex="-1">七、通用学习方法：四步闭环 <a class="header-anchor" href="#七、通用学习方法-四步闭环" aria-label="Permalink to &quot;七、通用学习方法：四步闭环&quot;">​</a></h2><ol><li><strong>读官方文档的「边界」章节</strong>：API 列表只能让你会用，Limitations / Caveats / Migration 才决定你会不会踩坑。</li><li><strong>在实验包写一个失败用例</strong>：先复现坑（时区错一天、订阅泄漏、原型污染、公式注入），再写修复，最后把用例留在 <code>test/</code> 里。</li><li><strong>读一层源码</strong>：不必通读，沿着「入口函数 → 核心分支 → 边界处理」走一遍；RxJS 看 <code>Observable.subscribe</code>，Zod 看 <code>_parse</code>，Lodash 看 <code>baseMerge</code>，Day.js 看 <code>$g</code> 与插件注册，XLSX 看 <code>write_zip</code> 的参数分支。</li><li><strong>做一次替换实验</strong>：把库换成原生实现或替代库，记录「哪些能力丢了、哪些坑消失了」——这是选型能力的来源。</li></ol><hr><h2 id="八、选型速查-什么时候不用这些库" tabindex="-1">八、选型速查：什么时候不用这些库 <a class="header-anchor" href="#八、选型速查-什么时候不用这些库" aria-label="Permalink to &quot;八、选型速查：什么时候不用这些库&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>更轻的方案</th><th>何时仍应选库</th></tr></thead><tbody><tr><td>只做 <code>YYYY-MM-DD</code> 展示</td><td><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>Intl.DateTimeFormat</code></a></td><td>需要大量日期运算、时区、相对时间、多语言</td></tr><tr><td>数组分组/去重/排序</td><td><code>Object.groupBy</code>、<code>Map</code>、<code>toSorted</code></td><td>复杂多级聚合、深路径读取、跨类型兼容</td></tr><tr><td>简单接口字段校验</td><td>手写守卫函数 + 类型收窄</td><td>表单/API/环境变量多边界复用、错误结构统一</td></tr><tr><td>单次点击请求、简单 loading</td><td><code>async/await + AbortController</code></td><td>多事件源合流、重试/超时/多播/复杂取消</td></tr><tr><td>小于 1 万行的一次性导出</td><td>手写 CSV + Blob</td><td>多 Sheet、格式、公式、日期、模板、大数据量</td></tr></tbody></table><hr><h2 id="九、结业验收-能全部做到即视为精通" tabindex="-1">九、结业验收（能全部做到即视为精通） <a class="header-anchor" href="#九、结业验收-能全部做到即视为精通" aria-label="Permalink to &quot;九、结业验收（能全部做到即视为精通）&quot;">​</a></h2><ul><li>[ ] 能解释五个库各自的「核心心智模型」，并各举一个不该用它的场景</li><li>[ ] 能为每个库写出「按需引入 + tree-shaking」正确的构建配置，并验证产物体积</li><li>[ ] 能定位并修复：时区错日、订阅泄漏、原型污染、公式注入、渲染期重建 Schema</li><li>[ ] 能为每个库写至少 5 个回归测试，覆盖正常、边界、失败三类输入</li><li>[ ] 能把五个库串成一条业务链，并给出「服务端做 / 客户端做」的取舍理由</li><li>[ ] 能读对应库的一层源码，说明一个 API 的内部实现路径</li></ul><hr><blockquote><p><strong>下一步</strong>：从 <a href="./32-dayjs">Day.js</a> 开始，先跑通 <code>libraries/packages/dayjs-lab</code> 的测试，再按「三阶段能力模型」逐站推进。遇到不确定的选型，回到本页的「选型速查」与各章「本章避坑清单」。</p></blockquote>`,60)])])}const g=e(a,[["render",l]]);export{b as __pageData,g as default};
